(() => {
  'use strict';
  const note = OpenDeskTool.root.querySelector('#selection-preview');
  const status = OpenDeskTool.root.querySelector('#selection-status');
  const save = OpenDeskTool.root.querySelector('#selection-save');
  const items = OpenDeskTool.root.querySelector('#selection-list');
  let launch = null;
  const message = (s) => { status.textContent = String(s); };
  const showNotes = (data) => {
    items.replaceChildren();
    for (const entry of data.slice().reverse()) {
      const li = document.createElement('li');
      li.textContent = entry.text;
      items.append(li);
    }
  };
  async function refresh() {
    const response = await OpenDeskTool.request('storage.get',{key:'notes'});
    const notes = Array.isArray(response.value) ? response.value : [];
    showNotes(notes);
    return notes;
  }
  OpenDeskSDK.browser.launch.consume().then(result => {
    if (typeof result.selection !== 'string' || !result.selection.trim()) {
      message('本次菜单动作没有安全可用的选区，不能保存。');
      return;
    }
    launch = result;
    note.textContent = result.selection;
    save.disabled = false;
    message('选区已领取，请点击“确认保存”；不会后台静默保存。');
  }).catch(error => {
    message('没有可领取的右键启动上下文：' + (error.code || error.message));
  });
  refresh().catch(error => message('读取记录失败：' + (error.code || error.message)));
  save.addEventListener('click', async event => {
    if (!event.isTrusted || !launch || save.disabled) return;
    const text = launch.selection.trim();
    if (!text) return;
    save.disabled = true;
    OpenDeskTool.setState({dirty:false,busy:true});
    try {
      const notes = await refresh();
      const next = [...notes,{text:text.slice(0,4000),source:launch.source.url}].slice(-12);
      await OpenDeskTool.request('storage.set',{key:'notes',value:next});
      await refresh();
      launch = null;
      message('已保存至此工具自己的本机存储。');
    } catch (error) {
      message('保存未确认，请检查记录后重试，不要假设写入失败：' + (error.code || error.message));
    } finally {
      OpenDeskTool.setState({dirty:false,busy:false});
    }
  });
})();
